  const dateStart = /^\s*((\d{1,2})[/-](\d{1,2})(?:[/-](\d{2,4}))?|(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)[a-z]*\.? \d{1,2}(?:,? \d{4})?)\b/i;
