  if (!twin || twin.tagName !== keep.tagName) return false;
  const chain = (el, top) => { const out = []; for (let x = el; x && x !== top; x = x.parentNode) out.unshift(x); return out; };
  const olds = chain(keep, root), news = chain(twin, tpl.content);
