  lunch: ['dining'], dinner: ['dining'], breakfast: ['dining'], coffee: ['coffee', 'dining'], doctor: ['medical', 'health', 'doctor'], pharmacy: ['medical', 'health', 'pharmacy'], dentist: ['dental', 'medical', 'health'],
