  const list = targets.slice(0, 4).map(t => `<li>${esc(txLabel(t))}<span class="muted"> · ${esc(catName(t.categoryId))}</span></li>`).join('') + (targets.length > 4 ? `<li class="muted">and ${targets.length - 4} more</li>` : '');
